"""90-degree angled flange mount for the Wuji and XHand hands.

Project rule: every hand end-effector rides on the same two-segment elbow
bracket the Sharpa hands use (``panda_sharpa_hand_right._generate_elbow_assets``:
Ø40 barrels, L1 = 32 mm axial, L2 = 28 mm horizontal, 0.15 kg). What differs per
hand is only the fixed mount rotation and the horizontal direction of segment 2.

How the numbers were obtained (v2, scratchpad ``fix_mount.py``):
measured on the COMMITTED Sharpa bracket, the hand root's +z axis -- which is the
mechanical mount-face normal, because every straight mount is a pure yaw about
the flange axis -- lands EXACTLY on ``_ELBOW_DW`` (0.56 deg). That is the rule:
the hand's mount face is PARALLEL to the bracket's plate, so the same machined
part bolts to any hand. The first derivation instead snapped the FINGERTIP MEAN
onto dW, which left the mount axis 17.7 deg (wuji R), 11.1 (wuji L), 4.1 (xhand R)
and 12.5 (xhand L) off the plate normal -- the visible skew the operator reported.

Each rotation below therefore sends the hand's mount axis exactly onto
``_ELBOW_DW`` and uses the remaining roll freedom to put the palm-facing normal
(measured as the direction the fingertips travel when every hand joint flexes
35 %, made perpendicular to the mount axis) exactly on the flange +z axis, i.e.
palm down when the flange points down. Segment 2 of the bracket keeps Sharpa's
direction on BOTH sides, exactly as the dual Sharpa agent does: one part number.

Values are mount rpy in the bracket/link8 frame; they already include the
straight mount's 135 deg docking yaw, since they replace that joint's origin.
"""
from __future__ import annotations

from pathlib import Path

from tasks.robots.panda_sharpa_hand_right import (
    _ELBOW_DW,
    _ELBOW_L1,
    _ELBOW_L2,
    _generate_elbow_assets,
)

ANGLED_MOUNTS = {
    ("wuji", "right"):  (-1.5708, -1.2727, -2.2742),
    ("wuji", "left"):   (-1.5708, -1.5263, -2.2742),
    ("xhand", "right"): (1.5708, -1.5463, 0.8674),
    ("xhand", "left"):  (-1.5708, -1.5463, -2.2742),
}

# How far the hand's own mount hub sits BEHIND its URDF root origin, so that the
# bracket's segment 2 ends at the hub's BACK face (the bolted surface) instead of
# at the root frame. Re-measured with the v2 rotations, against the
# committed Sharpa reference (its wrist back face sits -0.06 mm from the plate,
# i.e. flush): wuji's docking collar 28.0 mm, XHand's palm hull 0.0 mm. Before
# this the hands hung 4.5-5.0 mm off the plate.
HUB_DEPTH = {"wuji": 0.0280, "xhand": 0.0000}

# Lateral centring of the hand's mount face on the bracket's segment-2 axis, in
# the plate frame (ey = z x dW, ez = flange z). With the v2 rotations the mount
# face is parallel to the plate and its back-face centroid already lands on the
# axis by construction: measured residuals wuji +/-0.01 mm, XHand 1.02 / -0.73 mm,
# i.e. inside the committed Sharpa bracket's own 0.41 / 0.95 mm. The v1 values
# here (6-15 mm) were compensating for the skew and are gone.
LATERAL_OFFSET = {
    ("wuji", "right"):  (0.0, 0.0),
    ("wuji", "left"):   (0.0, 0.0),
    ("xhand", "right"): (0.0, 0.0),
    ("xhand", "left"):  (0.0, 0.0),
}

# The fixed flange->hand joint each URDF carries, per hand: (joint name template,
# child link template). ``{p}`` is the side prefix used by the dual URDFs
# ("left_"/"right_"); the single-arm URDFs have none on the arm side.
MOUNT_JOINTS = {
    "wuji": ("{p}panda_to_wuji_docking_joint", "{p}hand_docking_link"),
    "xhand": ("{p}panda_to_xhand_joint", "{side}_xhand_base_link"),
}


def _bracket_block(prefix: str, hand: str, side: str, child_link: str, joint_name: str, rel: str, ine: dict) -> str:
    rpy = ANGLED_MOUNTS[(hand, side)]
    dw = _ELBOW_DW          # one bracket part for every hand and both sides
    reach = _ELBOW_L2 + HUB_DEPTH[hand]
    dy, dz = LATERAL_OFFSET[(hand, side)]
    ey = (-dw[1], dw[0])                       # z x dW, horizontal, left of the finger direction
    xyz = (reach * dw[0] - dy * ey[0], reach * dw[1] - dy * ey[1], _ELBOW_L1 - dz)
    return f"""<link name="{prefix}angle_bracket">
    <inertial>
      <origin rpy="0 0 0" xyz="{ine['com'][0]:.5f} {ine['com'][1]:.5f} {ine['com'][2]:.5f}"/>
      <mass value="{ine['mass']:.3f}"/>
      <inertia ixx="{ine['ixx']:.3e}" iyy="{ine['iyy']:.3e}" izz="{ine['izz']:.3e}" ixy="{ine['ixy']:.3e}" ixz="{ine['ixz']:.3e}" iyz="{ine['iyz']:.3e}"/>
    </inertial>
    <visual><geometry><mesh filename="{rel}/elbow_visual.obj"/></geometry></visual>
    <collision><geometry><mesh filename="{rel}/elbow_col_a.obj"/></geometry></collision>
    <collision><geometry><mesh filename="{rel}/elbow_col_b.obj"/></geometry></collision>
  </link>
  <joint name="{prefix}panda_to_bracket_joint" type="fixed">
    <origin rpy="0 0 0" xyz="0 0 0"/>
    <parent link="{prefix}panda_link8"/>
    <child link="{prefix}angle_bracket"/>
  </joint>
  <joint name="{joint_name}" type="fixed">
    <origin rpy="{rpy[0]:.4f} {rpy[1]:.4f} {rpy[2]:.4f}" xyz="{xyz[0]:.5f} {xyz[1]:.5f} {xyz[2]:.5f}"/>
    <parent link="{prefix}angle_bracket"/>
    <child link="{child_link}"/>
  </joint>"""


def generate_angled_urdf(base: Path, out_name: str, hand: str, sides) -> str:
    """Rewrite ``base`` (a straight-mount URDF) with the elbow bracket on every
    listed side. ``sides`` = [("right", "")] for a single-arm URDF (no arm prefix)
    or [("left", "left_"), ("right", "right_")] for a dual one. Both new joints are
    fixed: zero added DOF, so controllers, gains and retargeting are untouched.
    Regenerated on import whenever the text would differ."""
    rel, ine = _generate_elbow_assets()
    base = Path(base)
    out = base.with_name(out_name)
    text = base.read_text()
    jt, ct = MOUNT_JOINTS[hand]
    for side, prefix in sides:
        joint_name = jt.format(p=prefix)
        child_link = ct.format(p=prefix, side=side)
        marker = f'<joint name="{joint_name}" type="fixed">'
        i = text.index(marker)
        j = text.index("</joint>", i) + len("</joint>")
        text = text[:i] + _bracket_block(prefix, hand, side, child_link, joint_name, rel, ine) + text[j:]
    if not out.exists() or out.read_text() != text:
        out.write_text(text)
    return str(out.resolve())
